import{_ as e,o as t,c as l,a2 as r}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"华特迪士尼 Walt Disney Company","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/迪士尼.md","filePath":"03_companies/迪士尼.md"}'),o={name:"03_companies/迪士尼.md"};function i(n,a,s,h,c,_){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="华特迪士尼-walt-disney-company" tabindex="-1">华特迪士尼 Walt Disney Company <a class="header-anchor" href="#华特迪士尼-walt-disney-company" aria-label="Permalink to &quot;华特迪士尼 Walt Disney Company&quot;">​</a></h1><h2 id="公司简介" tabindex="-1">公司简介 <a class="header-anchor" href="#公司简介" aria-label="Permalink to &quot;公司简介&quot;">​</a></h2><p>华特迪士尼公司是好莱坞最具标志性的娱乐帝国，业务涵盖电影制作、主题公园、电视广播和消费品。1995年，迪士尼以190亿美元收购美国广播公司（ABC），一跃成为全球最大媒体集团之一。巴菲特在这一时期成为<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>的重要股东，并公开表达对公司管理层的关注与期待。</p><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><ul><li><strong>1966年</strong>：巴菲特首次买入迪士尼股票，成本约每股0.31美元</li><li><strong>同年卖出</strong>：不久后以大幅盈利卖出全部股份</li><li><strong>1990年代中期</strong>：巴菲特重新买入迪士尼股份，成为重要股东</li><li><strong>1995年</strong>：迪士尼收购ABC期间，巴菲特公开支持这一战略（与<a href="/search.html?q=首都城市ABC">首都城市ABC</a>的资本运作紧密相关）</li><li><strong>1998年后</strong>：<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>逐步减持迪士尼</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特对迪士尼的投资贯穿了他对管理层、公司治理和内容价值的核心思考。1995年迪士尼收购ABC时，巴菲特公开表示支持，认为这是内容分发渠道的战略性整合——迪士尼的优质内容加上ABC的电视网络，能产生协同效应。</p><p>然而，巴菲特对迪士尼的长期关注也伴随着对管理层决策的审慎评估。迪士尼在迈克尔·艾斯纳（Michael Eisner）执掌后期，公司治理争议浮现——董事会结构问题、继承人规划缺失等问题引发投资者关注。巴菲特曾在公开场合表达对迪士尼治理结构的担忧，暗示优秀的管理层和健全的公司治理缺一不可——这一点也是他在<a href="/search.html?q=首都城市ABC">首都城市ABC</a>和<a href="/03_companies/可口可乐.html">可口可乐</a>等投资中反复强调的原则。</p><h2 id="关键语录" tabindex="-1">关键语录 <a class="header-anchor" href="#关键语录" aria-label="Permalink to &quot;关键语录&quot;">​</a></h2><blockquote><p>&quot;迪士尼拥有无可替代的内容资产——米老鼠、唐老鸭、白雪公主，这些IP的价值不会消失。问题在于谁来管理这些资产，以及管理层是否真正为股东利益服务。一家好公司，必须同时拥有好的管理层和好的治理结构。&quot;</p></blockquote><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1995年/翻译.html">/01_letters/1995年/翻译</a></li><li><a href="/01_letters/1996年/翻译.html">/01_letters/1996年/翻译</a></li><li><a href="/01_letters/1998年/翻译.html">/01_letters/1998年/翻译</a></li><li><a href="/01_letters/2012年/翻译.html">/01_letters/2012年/翻译</a></li></ul>',13)])])}const d=e(o,[["render",i]]);export{p as __pageData,d as default};
